package main

import "fmt"

// Map transforms a []T into a []U using f. T and U are independent type params.
func Map[T, U any](s []T, f func(T) U) []U {
	out := make([]U, len(s)) // pre-size for one allocation
	for i, v := range s {
		out[i] = f(v)
	}
	return out
}

// Filter keeps elements for which keep returns true.
func Filter[T any](s []T, keep func(T) bool) []T {
	out := make([]T, 0, len(s))
	for _, v := range s {
		if keep(v) {
			out = append(out, v)
		}
	}
	return out
}

// Stack is a generic LIFO container. T any means it holds any single type.
type Stack[T any] struct {
	items []T
}

// Methods use the receiver's T; they cannot declare new type parameters.
func (s *Stack[T]) Push(v T) { s.items = append(s.items, v) }

func (s *Stack[T]) Pop() (T, bool) {
	var zero T // the zero value of T when empty
	if len(s.items) == 0 {
		return zero, false
	}
	n := len(s.items) - 1
	v := s.items[n]
	s.items = s.items[:n]
	return v, true
}

func main() {
	nums := []int{1, 2, 3, 4}

	// Type inference: no [int, string] needed, the compiler infers from args.
	labels := Map(nums, func(n int) string { return fmt.Sprintf("#%d", n) })
	evens := Filter(nums, func(n int) bool { return n%2 == 0 })
	fmt.Println(labels, evens)

	var st Stack[string] // instantiate with a concrete type
	st.Push("a")
	st.Push("b")
	v, ok := st.Pop()
	fmt.Println(v, ok)
}

package main

import (
	"fmt"

	"golang.org/x/exp/constraints"
)

// Number permits these underlying types. ~ means "any type whose underlying
// type is this", so named types like Celsius (below) also satisfy it.
type Number interface {
	~int | ~int64 | ~float64
}

func Sum[T Number](nums []T) T {
	var total T // zero value: 0 for any numeric T
	for _, n := range nums {
		total += n // + is allowed because every type in the union supports it
	}
	return total
}

// Max uses the standard Ordered constraint (<, <=, >, >= and comparable).
func Max[T constraints.Ordered](s []T) T {
	m := s[0]
	for _, v := range s[1:] {
		if v > m {
			m = v
		}
	}
	return m
}

type Celsius float64 // underlying type float64, so it satisfies ~float64

func main() {
	fmt.Println(Sum([]int{1, 2, 3}))          // T inferred as int
	fmt.Println(Sum([]float64{1.5, 2.5}))     // T inferred as float64
	fmt.Println(Sum([]Celsius{10, 20, 12.5})) // named type works via ~float64

	fmt.Println(Max([]int{3, 9, 4}))          // Ordered covers integers
	fmt.Println(Max([]string{"a", "c", "b"})) // ...and strings
}
